const defaults = {"length":"normal","min":800,"max":1400,"style":"daily","custom":"","thoughtSummary":false,"preventTakeover":false};
const lengths = {short: [400, 700], normal: [800, 1400], long: [1600, 2400]};
const styles = {
  daily: ['现代日常', '用具体生活细节、自然口语对白与轻微幽默组织日常。关系从共同做事和即时回应中显露；保留人物差异、冲突和失落，不强行温情或治愈。'],
  novel: ['轻小说群像', '以清楚的动作、鲜明对白与人物反应形成节奏，可有符合人物口吻的自然吐槽；不堆砌夸张比喻，不把所有人写成同一种声音。'],
  plain: ['克制白描', '以准确、简洁的动作、对白及可观察细节推进场景，少作解释与评价，让具体变化和停顿承担表达。'],
  lyrical: ['细腻抒情', '通过环境、声音、动作节奏和留白呈现细腻氛围，语言清楚节制，不把普通小事强写成宏大情绪。'],
  mystery: ['悬疑写实', '重视可观察线索、行动因果与人物信息差，细节有依据，疑点来自已有事实；不为营造气氛硬造危险或暗中改写设定。'],
  custom: ['自定义文风', ''],
};
const thoughtTags = 'think|thinking|reasoning|analysis|ECoT|cot|draft|draft_notes|acg_think|lore_search|combat_driver|story_driver|dice_calculation|parallel_line_drive';
const noiseRules = [
  {key:'thought-blocks', label:'思考与草稿块', pattern:'<('+thoughtTags+')\\b[^>]*>[\\s\\S]*?(?:<\\/\\1\\s*>|$)', flags:'gi', replacement:'', raw:true},
  {key:'thought-fences', label:'思考与草稿代码块', pattern:'```(?:thinking|think|reasoning|analysis|cot|draft)\\b[^\\n]*\\r?\\n[\\s\\S]*?(?:```|$)', flags:'gi', replacement:'', raw:true},
  {key:'thought-heading', label:'思考过程前缀', pattern:'^\\s*(?:思考过程|推理过程|内部分析|analysis|thinking|reasoning)\\s*[:：][\\s\\S]*?(?=<content\\b|$)', flags:'i', replacement:'', raw:true},
  {key:'thought-closers', label:'残留思考闭合标签', pattern:'<\\/(?:'+thoughtTags+')\\s*>', flags:'gi', replacement:'', raw:true},
  {key:'transport-tail', label:'异常工具协议尾缀', pattern:'(<\\/(?:content|time)\\s*>\\s*)(?:```[^\\r\\n]*\\r?\\n)?(?:call\\s*:\\s*default_api\\s*:\\s*antitrunc_reply\\b|<\\|(?:im_end|eot_id|endoftext)\\|>|\\[DONE\\])[^]*$', flags:'gi', replacement:'$1', raw:true},
  {key:'partial-tag', label:'流式未完成标签', pattern:'<(?:[A-Za-z_/][^>\\r\\n]*)?$', flags:'g', replacement:'', raw:false},
];
function cleanOutput(raw, delimiters) {
  let text = String(raw ?? '').replace(/<xzs_plan\b[^>]*>[\s\S]*?(?:<\/xzs_plan\s*>|$)/gi, '').replace(/<xzs_summary\b[^>]*>[\s\S]*?(?:<\/xzs_summary\s*>|$)/gi, '');
  if (delimiters?.prefix && delimiters?.suffix) {
    const escape = value => String(value).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    text = text.replace(new RegExp(escape(delimiters.prefix)+'[\\s\\S]*?(?:'+escape(delimiters.suffix)+'|$)','g'), '');
  }
  for (const rule of noiseRules) text = text.replace(new RegExp(rule.pattern, rule.flags), rule.replacement);
  return text;
}
function normalizeConfig(value) {
  const c = {...defaults, ...value};
  if (!Object.hasOwn(lengths, c.length) && c.length !== 'custom') throw Error('请选择有效的字数档位。');
  if (!Object.hasOwn(styles, c.style)) throw Error('请选择有效的文风。');
  if (c.length !== 'custom') [c.min, c.max] = lengths[c.length];
  c.min = Number(c.min); c.max = Number(c.max);
  if (!Number.isInteger(c.min) || !Number.isInteger(c.max) || c.min < 100 || c.max > 10000 || c.min > c.max) throw Error('自定义字数须为100—10000之间的整数，且下限不高于上限。');
  c.preventTakeover = c.preventTakeover === true || c.preventTakeover === 'true';
  c.thoughtSummary = c.thoughtSummary === true || c.thoughtSummary === 'true';
  c.custom = String(c.custom ?? '').trim();
  if (c.style === 'custom' && !c.custom) throw Error('选择自定义文风时，请填写文风内容。');
  return c;
}
const preventTakeoverOriginal="# 本轮叙事任务：防抢话互动\n- <user_input>中的用户言行已发生，从其后写其他角色的回应及环境变化，不重演、不扩写用户刚完成的表演。\n- <user>完全由用户扮演：不添加其台词、心理、主动动作、表情、身体反应或决定；不借旁白、他人判断或省略时间暗示其已答应或采取行动。\n- 其他角色拥有完整的行动权：自行判断、决定、表态并采取能力范围内的行动，不把自己的处置选择交给<user>，也不把一切行动改成询问许可。\n- 不依赖<user>配合即可完成的事可以实际完成；需要<user>作出回应的互动，写清角色已经说了什么、做了什么，再将用户一方的反应留空。停在真实回应节点，不停在角色尚未开始行动之前。\n- 可以写其他角色发起动作及客观可见的环境后果，不擅自判定<user>顺从、失去行动能力或被带到下一场景。\n- 由当前回应形成自然停点，不为凑篇幅替双方来回对话或跳过用户回合。";
function playerControlPrompt(value){const c=normalizeConfig(value);return c.preventTakeover?'\n【用户设置：防抢话；<user>指玩家，<user_input>指本轮用户输入】\n'+preventTakeoverOriginal+'\n':'';}
function writingPrompt(value) {
  const c = normalizeConfig(value);
  return "<xzs_writing_config>\n【用户设置：正文篇幅与文风】\n正文目标：" + c.min + '—' + c.max + '个可见字符，优先写到区间中段约' + Math.round((c.min+c.max)/2) + '字。只计叙述与对白；空白、标签、思考、时间戳、协议标记和媒体控件不计。中文、标点、字母及数字各计一个字符。收束前核对正文篇幅：低于' + c.min + '字时补足当前互动的具体动作、对白与可观察细节，不把约数当作可以提前结束的理由。字数是写作目标，不通过截断补齐；扩写当前互动，不为了篇幅替玩家决定或增加事件、镜头和经过时间。\n当前文风：' + styles[c.style][0] + '。\n' + (c.style === 'custom' ? c.custom : styles[c.style][1]) + "\n" + (c.thoughtSummary ? "可见创作规划开启：回复开头输出一组<xzs_plan>…</xzs_plan>，闭合后再输出正文和时间字段。按四类索引及编号顺序组织；仅1.2“时间变化与最近节点”固定输出，其余只展开本轮相关项，不设最低项数，不要求四类齐全，不设独立总字数上限，规划不计入正文字数。规划中的本轮安排作用于紧接着的正文。展示用户可读的创作安排，不展示隐藏的逐步推理。\n【世界书原文】规则项直接使用本轮已载入子目的原文，按其原标题和UID标明来源。下面只列原文索引，不提供规则概述或替代正文；具体正文由世界书原生投放或原生原文引用提供。未载入的子目不声称已经核对；不根据分类名补写规则，不将原文改写成另一套禁令、条件或豁免。未相关的项目省略，不生成占位核对。\n【用户设置】正文篇幅、文风、视角、分项结构和时间/移动要求属于用户明确设置，单独标注，不冒称来自世界书。来源为当前聊天、角色资料或工具结果时同样标明实际来源，不混作世界书子目。\n" : '可见创作规划与约束核对关闭：直接输出正文，不添加<xzs_plan>或规划核对文字。\n') + playerControlPrompt(c) + '</xzs_writing_config>';
}
function bodyText(raw) {
  let text = cleanOutput(raw);
  const blocks = [...text.matchAll(/<content\b[^>]*>([\s\S]*?)(?:<\/content\s*>|$)/gi)];
  if (!blocks.length) return null;
  text = blocks.map(m => m[1]).join('\n');
  return text.replace(/<(time|bbs_start|bbs_end|audio|video|script|style|iframe)\b[^>]*>[\s\S]*?(?:<\/\1\s*>|$)/gi, '')
    .replace(/^\s*[\[【](?:场景事件|剧情触发|世界事件|奉心祭)[\]】].*$/gm, '')
    .replace(/<!--[^]*?(?:-->|$)/g, '')
    .replace(/【(?:歌曲|演奏|演出|点歌|照片|场景|场景事件|事件|主线|剧情|XZS)[^】]*】/g, '')
    .replace(/\[\[(?:XZS|SCENE|STORY)[^\]]*\]\]/gi, '')
    .replace(/<[^>]*>/g, '')
    .replace(/!\[[^\]]*\]\([^)]*\)/g, '').replace(/\[([^\]]*)\]\([^)]*\)/g, '$1').replace(/\*\*|__|~~|`/g, '')
    .replace(/&(?:amp|lt|gt|quot|apos|nbsp|#\d+|#x[\da-f]+);/gi, entity => {
      const named = {'&amp;':'&','&lt;':'<','&gt;':'>','&quot;':'"','&apos;':"'",'&nbsp;':' '}[entity.toLowerCase()];
      if (named !== undefined) return named;
      const hex = /^&#x/i.test(entity), point = parseInt(entity.slice(hex ? 3 : 2), hex ? 16 : 10);
      return point <= 0x10ffff ? String.fromCodePoint(point) : '\ufffd';
    })
    .replace(/[\s\u200b\ufeff]/g, '');
}
function bodyCount(raw) { const text = bodyText(raw); return text === null ? null : [...text].length; }

const planSections = [{"title":"Ⅰ·当前剧情与本轮任务","text":"【第一部分：当前剧情与本轮任务】\n1.1 【用户设置】当前玩家输入与本轮任务。\n1.2 【用户设置】时间变化与最近节点（固定）：列出当前有效起始时间、本轮动作与合理耗时、合计经过时间、结束时间，以及最近的相关校历/作息/约定/班次节点和剩余时间。时间依据直接使用《综合体-世界基石》（日常原文摘录 UID4194）；《时间流逝规则》（UID3823）；《校园·作息与学年》（UID4063）及当前有效聊天/工具结果。普通续写每轮最多经过15分钟，可更短；长途分轮接续，短途也写真实路径。玩家明确已抵达或明确要求直接写至抵达时可按该输入跳转；仅提出前往、给出起终点或选择路线不等于已抵达。并行动作和已结算等待不重复加时，预计行程不提前结算。动作触及最近节点时，在正文中承接该节点变化。\n1.3 原文：《综合体-世界基石》（日常原文摘录 UID4194）；《场所索引·场景落地》（UID3824）。\n1.4 原文：《角色扮演规范》（UID2232）；《全城通用·角色扮演限制器（读取勿动）》（UID2467）。\n1.5 【用户设置】沿用当前实际选择的文风、正文篇幅与视角，安排本轮收束位置。"},{"title":"Ⅱ·人物、身份与知识边界","text":"【第二部分：人物、身份与知识边界】\n2.1 【当前载入资料】直接使用本轮实际人物档案、名册与关系子目原文，写实际子目名称和UID。\n2.2 原文：《铁则-角色知识边界（反全知）》（UID18）。\n2.3 原文：《角色扮演规范》（UID2232）；《全城通用·角色扮演限制器（读取勿动）》（UID2467）；《铁则-班级社交枢纽：跨作品日常关系》（UID20）；《去职业病·生活化》（UID3674）；《群像均衡·多人场景调度》（UID3675）；《人际社交法则》（UID3676）；《real人际社交法则》（UID3801）；《real恋爱机制》（UID3802）；《去职业病3.0（都没用开这个/本条很长）》（UID3808）。\n2.4 原文：《衣物描写规范》（UID2348）；《铁则-既定外貌优先与面部库范围》（UID4135）；《命名规范》（UID2284）；《视觉创作总则》（UID2285）。"},{"title":"Ⅲ·场景与专门约束","text":"【第三部分：场景与专门约束】\n3.1 原文：《场所索引·场景落地》（UID3824）；《社团·总览与规则（读取勿动）》（UID2243）；《校园·作息与学年》（UID4063）。\n3.2 原文：《饮食描写规范》（UID2071）；《经济锚定·财富与生活逻辑》（UID3672）；《日常生理与卫生》（UID3673）；《群像均衡·多人场景调度》（UID3675）；《real基础生理需求》（UID3804）；《real疲惫机制(上班)》（UID3805）；《real疲惫机制(上学)》（UID3806）；《real衣服机制(根据四季)》（UID3807）；《美食世界书-使用总纲》（UID3813）；《挂世界书（二选一）》（UID3822）。\n3.3 原文：《主线总控（可选开启·默认关闭）》（UID2635）；《事件触发器·总控（读取勿动）》（UID3063）。\n3.4 【用户设置】位置转移与通勤：直接使用《地图·地理与导航规范》（UID2515）及本轮地图、电车、校内导航的真实结果，核对起点、具体目的地、交通工具、路线/换乘、预计耗时、本轮已走路段和真实停点。按1.2分段；短途交代既有道路、连廊、楼梯与沿途设施，长途续接本分支已走进度；时间与地点字段记录实际经过的这一段。\n3.5 【用户设置】音乐与媒体：涉及本轮实际演唱、演奏或播放时，直接使用已载入音乐/场景子目原文与实际曲库、脚本结果，标明实际来源；世界书资料包括《铁则-小手机与叙事正文的分工》（UID1996）；《城市文娱｜日常投放与分支边界》（UID3882）。\n3.6 场景专用约束仅按本轮实际挂载的内容核对；不显示原文和内部分类。\n3.7 【当前载入资料】其他本轮实际载入且相关的子目，直接沿用其原标题、UID与原文。"},{"title":"Ⅳ·禁词、文句与物理终检","text":"【第四部分：禁词、文句与物理终检】\n4.1 原文：《禁词表》（UID2234）。\n4.2 原文：《角色扮演规范》（UID2232）；《全城通用·角色扮演限制器（读取勿动）》（UID2467）；《去职业病·生活化》（UID3674）；《去职业病3.0（都没用开这个/本条很长）》（UID3808）。\n4.3 原文：《综合体-世界基石》（日常原文摘录 UID4194）；《地图·地理与导航规范》（UID2515）；《衣物描写规范》（UID2348）。\n4.4 原文：《铁则-小手机与叙事正文的分工》（UID1996）。"}];
function planSectionPrompt(index,value) { const c=normalizeConfig(value);return '<xzs_plan_section id="'+index+'">\n'+(c.thoughtSummary?planSections[index-1].text:'本轮创作规划关闭，不输出本部分。')+'\n</xzs_plan_section>'; }

